const vr = $json.valueRanges || [];
const el = (vr[0] && vr[0].values) || [];
const inv = (vr[1] && vr[1].values) || [];
const cr = (vr[2] && vr[2].values) || [];
const norm = s => String(s == null ? '' : s).trim();
const key = s => norm(s).toLowerCase().replace(/[^a-z0-9]+/g,'');

// ---- ERROR LOG ----
const elH = (el[0]||[]).map(h => key(h));
const ci = n => elH.indexOf(n);
const iTs = ci('timestamp') >= 0 ? ci('timestamp') : 0;
const iWf = ci('workflow');
const iType = ci('type') >= 0 ? ci('type') : ci('errortype');
const iDet = ci('details') >= 0 ? ci('details') : ci('detail');
const iRes = ci('resolved');
const unresolved = [];
const byWf = {};
for (let r = 1; r < el.length; r++) {
  const row = el[r] || [];
  if (!row.some(c => norm(c))) continue;
  const res = iRes >= 0 ? norm(row[iRes]) : '';
  if (res) continue;
  const wf = iWf >= 0 ? norm(row[iWf]) : '';
  byWf[wf || '(blank)'] = (byWf[wf || '(blank)'] || 0) + 1;
  if (/THESIS/i.test(wf)) {
    unresolved.push({ row: r + 1, ts: norm(row[iTs]).slice(0,16), wf, type: iType>=0?norm(row[iType]):'', details: (iDet>=0?norm(row[iDet]):'').slice(0,200) });
  }
}

// ---- INVESTORS vs CRITERIA ----
const invH = (inv[0]||[]).map(h => key(h));
const pos = (names, def) => { for (const n of names) { const i = invH.indexOf(n); if (i >= 0) return i; } return def; };
const iName = pos(['investorname','investor','name','firm'], 0);
const iContact = pos(['contactperson','contact','contactname'], 1);
const iEmail = pos(['email','emailaddress'], 2);
const iSector = pos(['sector','sectors'], 4);
const iStage = pos(['stage','stages'], 5);
const iCheque = pos(['chequesize','cheque','ticketsize'], 6);
const iDnc = invH.indexOf('donotcontact');

const crH = (cr[0]||[]).map(h => key(h));
const cpos = n => crH.indexOf(n);
const cInvestor = cpos('investor') >= 0 ? cpos('investor') : 1;
const cSheetRow = cpos('sheetrow');
const cStatus = cpos('status');
const cConfirmed = cpos('confirmed');
const cReview = cpos('reviewreason');
const cSectorsIn = cpos('sectorsin');
const cStageMin = cpos('stagemin');
const cStageMax = cpos('stagemax');

const critByName = new Map();
const critRows = [];
for (let r = 1; r < cr.length; r++) {
  const row = cr[r] || [];
  const nm = norm(row[cInvestor]);
  if (!nm) continue;
  const o = { row: r + 1, name: nm, sheet_row: cSheetRow>=0?norm(row[cSheetRow]):'', status: cStatus>=0?norm(row[cStatus]):'', confirmed: cConfirmed>=0?norm(row[cConfirmed]):'', review: cReview>=0?norm(row[cReview]).slice(0,120):'', sectors_in: cSectorsIn>=0?norm(row[cSectorsIn]).slice(0,60):'', stage_min: cStageMin>=0?norm(row[cStageMin]):'', stage_max: cStageMax>=0?norm(row[cStageMax]):'' };
  critRows.push(o);
  critByName.set(key(nm), o);
}

const missing = [];
const dupNames = [];
const seenName = new Map();
const emailIdx = new Map();
const dupEmail = [];
for (let r = 1; r < inv.length; r++) {
  const row = inv[r] || [];
  const nm = norm(row[iName]);
  if (!nm && !norm(row[iContact]) && !norm(row[iEmail])) continue;
  const rowNo = r + 1;
  const k = key(nm);
  if (k) { if (seenName.has(k)) dupNames.push({ name: nm, rows: [seenName.get(k), rowNo] }); else seenName.set(k, rowNo); }
  const emails = norm(row[iEmail]).toLowerCase().split(/[,;\s]+/).filter(e => e.includes('@'));
  for (const e of emails) { if (emailIdx.has(e)) { dupEmail.push({ email: e, rows: [emailIdx.get(e), rowNo], names: [null, nm] }); } else emailIdx.set(e, rowNo); }
  if (!k || !critByName.has(k)) {
    missing.push({ row: rowNo, name: nm || '(blank name)', contact: norm(row[iContact]).slice(0,40), email: norm(row[iEmail]).slice(0,60), sector: norm(row[iSector]).slice(0,70), stage: norm(row[iStage]).slice(0,40), cheque: norm(row[iCheque]).slice(0,40), dnc: iDnc>=0?norm(row[iDnc]):'' });
  }
}

const pending = critRows.filter(o => /PENDING/i.test(o.confirmed));
const pendingCompact = pending.map(o => o.row + ':' + o.name + (o.status ? '/' + o.status : ''));
const holds = critRows.filter(o => /HOLD/i.test(o.status)).map(o => o.row + ':' + o.name);

return [{ json: {
  error_log_rows: el.length - 1,
  unresolved_by_workflow: byWf,
  unresolved_thesis_count: unresolved.length,
  unresolved_thesis: unresolved.slice(0, 30),
  investors_rows: inv.length - 1,
  criteria_rows: critRows.length,
  investors_without_criteria_count: missing.length,
  investors_without_criteria: missing.slice(0, 40),
  duplicate_investor_names: dupNames.slice(0, 20),
  duplicate_emails_count: dupEmail.length,
  duplicate_emails: dupEmail.slice(0, 15),
  pending_count: pending.length,
  pending_list: pendingCompact.slice(0, 60),
  hold_count: holds.length,
  hold_list: holds.slice(0, 40),
  el_headers: (el[0]||[]),
  el_detail: [2649,2650,2651,2652,2653,2654,2655,2656].map(n => ({row:n, cells:(el[n-1]||[]).map(c=>String(c==null?'':c).slice(0,300))})),
  crit_template: [246,261,274].map(n => ({row:n, cells:(cr[n-1]||[])})),
  raw_new: [42,284,285,286,287,288].map(n => ({row:n, cells:(inv[n-1]||[]).slice(0,10)})),
  same_firm_rows: inv.map((r,i)=>({row:i+1,name:norm((r||[])[iName]),email:norm((r||[])[iEmail])})).filter(o=>/tvs|rainmatter|seafund|cisco|dexter/i.test(o.name)),
  investors_headers: (inv[0]||[]).slice(0,10),
  criteria_headers: (cr[0]||[]).slice(0,29)
} }];
